	void constantFalseGuardChecksEntryBindingsBeforeDelegating(boolean fallbackAccepts) {
		TrackingFilter fallback = new TrackingFilter(fallbackAccepts, KernelTermKindProof.unknown());
		NativeConstantFalseWhenUnboundFilter guard = new NativeConstantFalseWhenUnboundFilter(
				new String[] { "entry" }, fallback);
		RowState unbound = row(EmptyBindingSet.getInstance());
		QueryBindingSet supplied = new QueryBindingSet();
		supplied.addBinding("entry", SimpleValueFactory.getInstance().createIRI("urn:test:entry"));
		RowState bound = row(supplied);

		assertTrue(guard.constantFalse(unbound.base));
		assertFalse(guard.constantFalse(bound.base));
		assertFalse(guard.accept(unbound));
		if (fallbackAccepts) {
			assertTrue(guard.accept(bound));
		} else {
			assertFalse(guard.accept(bound));
		}
		assertEquals(1, fallback.acceptCalls,
				"the fallback must run only after every required entry binding is present");
	}

	@Test
	void constantFalseGuardCannotExposeAnUnboundUnsafeProofThroughComposition() {
		int literal = 1 << ValueIds.TERM_KIND_LITERAL;
		KernelTermKindProof fallbackProof = KernelTermKindProof.forKind(0, literal);
		NativeConstantFalseWhenUnboundFilter guard = new NativeConstantFalseWhenUnboundFilter(
				new String[] { "entry" }, new TrackingFilter(true, fallbackProof));
		NativeBooleanFilter composed = new CloseOnceNativeBooleanFilter(
				new RecordingNativeBooleanFilter(guard, mock(Filter.class), new EvaluationStatistics()));

		assertConservativeForUnboundEntry(guard.pageProof(new int[] { 0 }), literal);
		assertConservativeForUnboundEntry(composed.pageProof(new int[] { 0 }), literal);
	}

	private static void assertConservativeForUnboundEntry(KernelTermKindProof proof, int literal) {
		// pageProof has no entry BindingSet parameter. It may therefore decline the proof, or retain only a proof that
		// still includes FALSE when the fallback would otherwise claim TRUE for a literal page.
		if (proof != null) {
			int literalOutcomes = proof.evaluate(ignored -> literal);
			assertTrue((literalOutcomes & KernelTermKindProof.TRUE_BIT) != 0,
					"a bound entry must retain the fallback's possible acceptance");
			assertTrue((literalOutcomes & KernelTermKindProof.FALSE_BIT) != 0,
					"an unbound entry must remain a possible rejection");
			assertTrue((proof.evaluate(ignored -> 1 << ValueIds.TERM_KIND_IRI)
					& KernelTermKindProof.FALSE_BIT) != 0,
					"a known fallback rejection must remain a possible rejection");
		}
	}

